        Loc.Add("export.layout.pickMod", "Choose the mod folder", "Mod-Ordner wählen", "Elegir la carpeta del mod", "Choisir le dossier du mod", "Scegli la cartella della mod", "Выбрать папку мода", "选择模组文件夹");
